            <div class="mt-5 grid gap-3 sm:grid-cols-3"><Mini label="Readiness" :value="readinessLabel(unit.readiness_status)" :alert="unit.readiness_status && unit.readiness_status !== 'ready'"/><Mini label="Credential" :value="unit.credential_alert ? 'Expired / review' : 'Clear'" :alert="unit.credential_alert"/><Mini label="Open maintenance" :value="String(unit.open_maintenance || 0)" :alert="unit.open_maintenance > 0"/></div>
