ext-red-300">Critical issue / take unit out of service</span><span class="mt-1 block text-[0.68rem] leading-5 text-red-600/70 dark:text-red-300/60">This records Out of Service and automatically moves an idle unit to Maintenance.</span></span></label><label class="block"><span :class="labelClass">Notes</span><textarea v-model.trim="readinessForm.notes" rows="3" :class="`${fieldClass} resize-none`" placeholder="Issues found, supplies to replenish, or inspection notes"/></label></div><footer class="flex justify-end gap-2 border-t border-base-300 p-5 dark:border-white/10 sm:p-6"><button class="rounded-xl border border-base-300 px-4 py-2.5 text-sm font-bold text-slate-600" @click="readinessOpen=false">Cancel</button><button class="rounded-xl bg-[#1976D2] px-5 py-2.5 text-sm font-bold text-white disabled:opacity-50" :disabled="savingReadiness" @click="saveCheck">{{ savingReadiness ? 'Saving…' : 'Save Check' }}</button></footer></section></div>

      <!-- maintenance create -->
      <div v-if="maintenanceOpen" class="fixed inset-0 z-[97] grid place-items-center bg-slate-950/55 p-4 backdrop-blur-sm" @click.self="maintenanceOpen=false"><section class="w-full max-w-xl rounded-[28px] border border-base-300 bg-base-100 shadow-2xl dark:border-white/10 dark:bg-[#0d2943]"><header class="border-b border-base-300 p-5 dark:border-white/10"><p class="text-[0.68rem] font-black uppercase tracking-[0.14em] text-red-600">Fleet maintenance</p><h2 class="mt-1 text-xl font-black text-slate-950 dark:text-white">Maintenance Record · {{ selectedUnit?.unit_code }}</h2></header><div class="grid gap-4 p-5 sm:grid-cols-2"><label><span :class="labelClass">Type</span><select v-model="maintenanceForm.maintenance_type" :class="fieldClass"><option value="preventive">Preventive</option><option value="repair">Repair</option><option value="inspection">Inspection</option><option value="other">Other</option></select></label><label><span :class="labelClass">Status</span><select v-model="maintenanceForm.status" :class="fieldClass"><option value="scheduled">Scheduled</option><option value="in_progress">In progress</option></select></label><label><span :class="labelClass">Scheduled date</span><input v-model="maintenanceForm.scheduled_for" type="date" :class="fieldClass"/></label><label><span :class="labelClass">Provider / workshop</span><input v-model.trim="maintenanceForm.provider" :class="fieldClass" placeholder="Optional"/></label><label><span :class="labelClass">Cost</span><input v-model="maintenanceForm.cost" type="number" min="0" step="0.01" :class="fieldClass" placeholder="Optional"/></label><label class="sm:col-span-2"><span :class="labelClass">Notes</span><textarea v-model.trim="maintenanceForm.notes" rows="3" :class="`${fieldClass} resize-none`" placeholder="Work required, inspection findings, or service details"/></label></div><footer class="flex justify-end gap-2 border-t border-base-300 p-5 dark:border-white/10"><button class="rounded-xl border border-base-300 px-4 py-2.5 text-sm font-bold text-slate-600" @click="maintenanceOpen=false">Cancel</button><button class="rounded-xl bg-red-600 px-5 py-2.5 text-sm font-bold text-white disabled:opacity-50" :disabled="savingMaintenance" @click="saveMaintenance">{{ savingMaintenance ? 'Saving…' : 'Create Record' }}</button></footer></section></div>

      <!-- history drawer -->
      <div v-if="historyOpen" class="fixed inset-0 z-[94] flex justify-end bg-slate-950/55 backdrop-blur-sm" @click.self="historyOpen=false"><aside class="h-full w-full max-w-2xl overflow-y-auto border-l border-base-300 bg-base-100 shadow-2xl dark:border-white/10 dark:bg-[#0d2943]"><div v-if="historyLoading" class="p-8"><div class="h-28 animate-pulse rounded-3xl bg-base-200 dark:bg-white/5"></div></div><template v-else-if="history?.unit"><header class="sticky top-0 z-10 flex items-start justify-between border-b border-base-300 bg-base-100/95 p-5 backdrop-blur dark:border-white/10 dark:bg-[#0d2943]/95"><div><p class="text-[0.68rem] font-black uppercase tracking-[0.14em] text-[#1976D2]">Fleet history</p><h2 class="mt-1 text-xl font-black text-slate-950 dark:text-white">{{ history.unit.unit_code }}</h2></div><button class="rounded-xl p-2 text-slate-400 hover:bg-base-200" @click="historyOpen=false"><Icon icon="lucide:x" width="18"/></button></header><div class="space-y-6 p-5 sm:p-6"><section><h3 class="text-sm font-black text-slate-800 dark:text-white/70">Readiness checks</h3><div class="mt-3 space-y-3"><div v-for="r in history.readiness_checks" :key="r.id" class="rounded-2xl border border-base-300 p-4 dark:border-white/5"><div class="flex items-center justify-between gap-2"><ReadinessPill :value="r.overall_status"/><span class="text-[0.62rem] text-slate-400">{{ formatDateTime(r.checked_at) }}</span></div><p class="mt-2 text-[0.68rem] text-slate-500 dark:text-white/35">Fuel {{ r.fuel_level }} · {{ r.checked_by_name?.trim() || 'Organization staff' }}</p><p v-if="r.notes" class="mt-2 text-[0.68rem] leading-5 text-slate-400">{{ r.notes }}</p></div><p v-if="!history.readiness_checks?.length" class="rounded-2xl bg-base-200 p-4 text-xs text-slate-400">No readiness checks recorded.</p></div></section><section><h3 class="text-sm font-black text-slate-800 dark:text-white/70">Maintenance records</h3><div class="mt-3 space-y-3"><div v-for="m in history.maintenance_records" :key="m.id" class="rounded-2xl border border-base-300 p-4 dark:border-white/5"><div class="flex items-start justify-between gap-3"><div><p class="text-xs font-black text-slate-700 dark:text-white/65">{{ maintenanceTypeLabel(m.maintenance_type) }}</p><p class="mt-1 text-[0.65rem] text-slate-400">{{ m.provider || 'No provider' }} · {{ m.scheduled_for ? formatDate(m.scheduled_for) : 'No scheduled date' }}</p></div><span class="rounded-full bg-base-200 px-2.5 py-1 text-[0.62rem] font-bold text-slate-600 dark:bg-white/5 dark:text-white/45">{{ maintenanceStatusLabel(m.status) }}</span></div><p v-if="m.notes" class="mt-2 text-[0.68rem] leading-5 text-slate-400">{{ m.notes }}</p><div v-if="canMaintenanceUpdate && !['completed','cancelled'].includes(m.status)" class="mt-3 flex gap-2"><button v-if="m.status==='scheduled'" class="rounded-lg bg-amber-100 px-2.5 py-1.5 text-[0.65rem] font-bold text-amber-700" @click="setMaintenanceStatus(m,'in_progress')">Start</button><button class="rounded-lg bg-emerald-100 px-2.5 py-1.5 text-[0.65rem] font-bold text-emerald-700" @click="setMaintenanceStatus(m,'completed')">Complete</button><button class="rounded-lg bg-base-200 px-2.5 py-1.5 text-[0.65rem] font-bold text-slate-500" @click="setMaintenanceStatus(m,'cancelled')">Cancel</button></div></div><p v-if="!history.maintenance_records?.length" class="rounded-2xl bg-base-200 p-4 text-xs text-slate-400">No maintenance records recorded.</p></div></section></div></template></aside></div>
    </div>
  </section>
</template>

<script setup>
import { computed, defineComponent, h, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { Icon } from '@iconify/vue'
import { createMaintenanceRecord, fetchFleetUnit, fetchFleetUnits, saveReadinessCheck, updateMaintenanceRecord } from '@/services/organizationFleet'
import { useSession } from '@/composables/useSession'
import { useToast } from '@/composables/useToast'

const { hasPermission }=useSession();const toast=useToast()
const loading=ref(true),errorMessage=ref(''),units=ref([]),stats=ref({ready:0,attention:0,maintenance:0,credential_alerts:0})
const selectedUnit=ref(null),readinessOpen=ref(false),maintenanceOpen=ref(false),historyOpen=ref(false),historyLoading=ref(false),history=ref(null),savingReadiness=ref(false),savingMaintenance=ref(false)
const readinessForm=ref({fuel_level:'adequate',oxygen_ready:true,medical_supplies_ready:true,lights_siren_ready:true,communications_ready:true,stretcher_ready:true,cleanliness_ready:true,critical_issue:false,notes:''})
const maintenanceForm=ref({maintenance_type:'preventive',status:'scheduled',scheduled_for:'',provider:'',cost:'',notes:''})
const fieldClass='w-full rounded-xl border border-base-300 bg-base-100 px-3.5 py-2.5 text-sm text-slate-800 outline-none transition focus:border-[#1976D2] focus:ring-2 focus:ring-[#1976D2]/10 dark:border-white/10 dark:bg-[#071829] dark:text-white'
const labelClass='mb-1.5 block text-[0.68rem] font-black uppercase tracking-wide text-slate-400 dark:text-white/30'
const canReadiness=computed(()=>hasPermission('fleet.ambulance_readiness.update')),canMaintenanceCreate=computed(()=>hasPermission('fleet.maintenance_records.create')),canMaintenanceUpdate=computed(()=>hasPermission('fleet.maintenance_records.update'))
const typeLabel=v=>({basic_life_support:'Basic Life Support',advanced_life_support:'Advanced Life Support',patient_transport:'Patient Transport',rescue_unit:'Rescue Unit'}[v]||v)
const statusLabel=v=>({available:'Available',reserved:'Reserved',dispatched:'Dispatched',on_scene:'On scene',transporting:'Transporting',returning:'Returning',maintenance:'Maintenance',offline:'Offline'}[v]||v)
const readinessLabel=v=>({ready:'Ready',needs_attention:'Needs attention',out_of_service:'Out of service'}[v]||'Not checked')
const maintenanceTypeLabel=v=>({preventive:'Preventive maintenance',repair:'Repair',inspection:'Inspection',other:'Other'}[v]||v)
const maintenanceStatusLabel=v=>({scheduled:'Scheduled',in_progress:'In progress',completed:'Completed',cancelled:'Cancelled'}[v]||v)
const formatDate=v=>v?new Date(`${String(v).slice(0,10)}T00:00:00`).toLocaleDateString([], {month:'short',day:'numeric',year:'numeric'}):'—'
const formatDateTime=v=>v?new Date(String(v).replace(' ','T')).toLocaleString():'—'
const Stat=defineComponent({props:{label:String,value:[String,Number],icon:String,hint:String},setup(p){return()=>h('article',{class:'rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#0d2943]'},[h('div',{class:'flex items-start justify-between'},[h('span',{class:'grid h-10 w-10 place-items-center rounded-2xl bg-base-200 text-slate-500 dark:bg-white/5 dark:text-white/40'},[h(Icon,{icon:p.icon,width:19})]),h('span',{class:'text-2xl font-black text-slate-950 dark:text-white'},String(p.value??0))]),h('p',{class:'mt-4 text-sm font-black text-slate-800 dark:text-white/70'},p.label),h('p',{class:'mt-1 text-xs leading-5 text-slate-400 dark:text-white/30'},p.hint)])}})
const Mini=defineComponent({props:{label:String,value:String,alert:Boolean},setup(p){return()=>h('div',{class:'rounded-2xl bg-base-200 p-3 dark:bg-white/[0.035]'},[h('p',{class:'text-[0.6rem] font-black uppercase tracking-wide text-slate-400'},p.label),h('p',{class:['mt-1 text-xs font-black',p.alert?'text-amber-600 dark:text-amber-300':'text-slate-700 dark:text-white/60']},p.value)])}})
const StatusPill=defineComponent({props:{value:String},setup(p){return()=>h('span',{class:['rounded-full px-2 py-1 text-[0.6rem] font-bold',p.value==='available'?'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300':p.value==='maintenance'?'bg-amber-100 text-amber-700 dark:bg-amber-500/15 dark:text-amber-300':'bg-base-200 text-slate-600 dark:bg-white/5 dark:text-white/45']},statusLabel(p.value))}})
const ReadinessPill=defineComponent({props:{value:String},setup(p){return()=>h('span',{class:['inline-flex rounded-full px-2.5 py-1 text-[0.62rem] font-bold',p.value==='ready'?'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300':p.value==='out_of_service'?'bg-red-100 text-red-700 dark:bg-red-500/15 dark:text-red-300':'bg-amber-100 text-amber-700 dark:bg-amber-500/15 dark:text-amber-300']},readinessLabel(p.value))}})
const Check=defineComponent({props:{modelValue:Boolean,label:String,icon:String},emits:['update:modelValue'],setup(p,{emit}){return()=>h('label',{class:'flex cursor-pointer items-center gap-3 rounded-2xl border border-base-300 p-3.5 dark:border-white/10'},[h('span',{class:'grid h-8 w-8 place-items-center rounded-xl bg-base-200 text-slate-500 dark:bg-white/5 dark:text-white/40'},[h(Icon,{icon:p.icon,width:15})]),h('span',{class:'min-w-0 flex-1 text-xs font-bold text-slate-700 dark:text-white/55'},p.label),h('input',{type:'checkbox',checked:p.modelValue,class:'h-4 w-4 accent-[#1976D2]',onChange:e=>emit('update:modelValue',e.target.checked)})])}})

async function load(){loading.value=true;errorMessage.value='';try{const r=await fetchFleetUnits();units.value=r.units||[];stats.value=r.stats||stats.value}catch(e){errorMessage.value=e?.response?.data?.message||'Could not load fleet readiness.'}finally{loading.value=false}}
function openReadiness(unit){selectedUnit.value=unit;readinessForm.value={fuel_level:'adequate',oxygen_ready:true,medical_supplies_ready:true,lights_siren_ready:true,communications_ready:true,stretcher_ready:true,cleanliness_ready:true,critical_issue:false,notes:''};readinessOpen.value=true}
async function saveCheck(){savingReadiness.value=true;try{const r=await saveReadinessCheck({ambulance_id:selectedUnit.value.id,...readinessForm.value});toast.success(r.message);readinessOpen.value=false;await load()}catch(e){toast.error(e?.response?.data?.message||'Could not save readiness check.')}finally{savingReadiness.value=false}}
function openMaintenance(unit){selectedUnit.value=unit;maintenanceForm.value={maintenance_type:'preventive',status:'scheduled',scheduled_for:'',provider:'',cost:'',notes:''};maintenanceOpen.value=true}
async function saveMaintenance(){savingMaintenance.value=true;try{const r=await createMaintenanceRecord({ambulance_id:selectedUnit.value.id,...maintenanceForm.value});toast.success(r.message);maintenanceOpen.value=false;await load()}catch(e){toast.error(e?.response?.data?.message||'Could not create maintenance record.')}finally{savingMaintenance.value=false}}
async function openHistory(id){historyOpen.value=true;historyLoading.value=true;try{history.value=await fetchFleetUnit(id)}catch(e){toast.error(e?.response?.data?.message||'Could not load fleet history.');historyOpen.value=false}finally{historyLoading.value=false}}
async function setMaintenanceStatus(record,status){try{const r=await updateMaintenanceRecord({id:record.id,status,notes:record.notes||''});toast.success(r.message);history.value=await fetchFleetUnit(history.value.unit.id);await load()}catch(e){toast.error(e?.response?.data?.message||'Could not update maintenance.')}}
onMounted(load)
</script>
